#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): with its defaults this feature has no CA to
# install, so it fails by design and this script is not reached there. It
# is kept for a local run with an image that supplies a CA (for example
# `devcontainer features test -f ssl-ca -i <image with SSL_CA_CERTS>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=ssl-ca-checks.sh
source "$(dirname "$0")/ssl-ca-checks.sh"

check "containerEnv points the CA variables at the system bundle" container_env_ok
check "the system bundle exists" test -s "$BUNDLE"

reportResults
